-- Platform completion for the dashboard rebuild.
-- Review and run this yourself. Do not apply it from the app.
-- Do not edit this file in a later phase. Do not apply 0022.
--
-- Writes go through the service role, which bypasses RLS.
-- Owner and reseller policies are select-only, matching 0025 and 0029.
-- NULL tenant_id is the owner store.

-- ---------------------------------------------------------------------------
-- platform_settings: store open/closed, reseller policy, fraud thresholds
-- ---------------------------------------------------------------------------

alter table platform_settings
  add column if not exists store_status text not null default 'open',
  add column if not exists maintenance_msg text,
  add column if not exists reseller_policy jsonb not null default '{}'::jsonb,
  add column if not exists fraud_orders_per_hour integer not null default 20,
  add column if not exists fraud_orders_per_day integer not null default 50,
  add column if not exists fraud_failed_claims_per_hour integer not null default 5,
  add column if not exists fraud_support_messages_per_hour integer not null default 30,
  add column if not exists fraud_referral_claims_per_day integer not null default 10,
  add column if not exists fraud_new_account_order_cap integer not null default 3,
  add column if not exists fraud_new_account_age_hours integer not null default 24;

alter table platform_settings
  drop constraint if exists platform_settings_store_status_chk;
alter table platform_settings
  add constraint platform_settings_store_status_chk
  check (store_status in ('open', 'maintenance'));

alter table platform_settings
  drop constraint if exists platform_settings_reseller_policy_obj_chk;
alter table platform_settings
  add constraint platform_settings_reseller_policy_obj_chk
  check (jsonb_typeof(reseller_policy) = 'object');

alter table platform_settings
  drop constraint if exists platform_settings_fraud_thresholds_chk;
alter table platform_settings
  add constraint platform_settings_fraud_thresholds_chk
  check (
    fraud_orders_per_hour > 0
    and fraud_orders_per_day > 0
    and fraud_failed_claims_per_hour > 0
    and fraud_support_messages_per_hour > 0
    and fraud_referral_claims_per_day > 0
    and fraud_new_account_order_cap > 0
    and fraud_new_account_age_hours > 0
  );

-- ---------------------------------------------------------------------------
-- customers: when and why a buyer was blocked
-- is_blocked already exists. These columns record the decision.
-- ---------------------------------------------------------------------------

alter table customers
  add column if not exists blocked_at timestamptz,
  add column if not exists blocked_reason text;

alter table customers
  drop constraint if exists customers_blocked_reason_len_chk;
alter table customers
  add constraint customers_blocked_reason_len_chk
  check (blocked_reason is null or char_length(blocked_reason) <= 500);

create index if not exists customers_blocked_at_idx
  on customers (blocked_at)
  where blocked_at is not null;

-- ---------------------------------------------------------------------------
-- support inbox
-- ---------------------------------------------------------------------------

create table if not exists support_threads (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade,
  customer_id uuid not null references customers(id) on delete cascade,
  bot_id uuid references bot_connections(id) on delete set null,
  status text not null default 'open',
  last_message_at timestamptz not null default now(),
  unread_for_owner boolean not null default false,
  created_at timestamptz not null default now(),
  constraint support_threads_status_chk check (status in ('open', 'closed'))
);

create index if not exists support_threads_inbox_idx
  on support_threads (tenant_id, unread_for_owner desc, last_message_at desc);

create index if not exists support_threads_customer_idx
  on support_threads (customer_id, last_message_at desc);

create table if not exists support_messages (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references support_threads(id) on delete cascade,
  sender text not null,
  body text not null,
  created_at timestamptz not null default now(),
  constraint support_messages_sender_chk check (sender in ('customer', 'owner')),
  constraint support_messages_body_len_chk check (char_length(body) between 1 and 2000)
);

create index if not exists support_messages_thread_idx
  on support_messages (thread_id, created_at);

-- ---------------------------------------------------------------------------
-- discount codes
-- code is stored upper-case. Percent value is 0–100. Fixed value is minor units.
-- A plain unique (tenant_id, code) would allow duplicate owner codes, because
-- NULL tenant_id is distinct. The expression index treats the owner store as
-- one tenant, matching store_config in 0025.
-- ---------------------------------------------------------------------------

create table if not exists discount_codes (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade,
  code text not null,
  kind text not null,
  value numeric(18, 4) not null,
  min_order_minor bigint not null default 0,
  max_uses integer,
  used_count integer not null default 0,
  per_customer_limit integer,
  starts_at timestamptz,
  expires_at timestamptz,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint discount_codes_code_chk check (
    code = upper(code)
    and char_length(code) between 3 and 32
    and code ~ '^[A-Z0-9][A-Z0-9_-]*$'
  ),
  constraint discount_codes_kind_chk check (kind in ('percent', 'fixed')),
  constraint discount_codes_value_chk check (
    value > 0
    and (kind <> 'percent' or value <= 100)
  ),
  constraint discount_codes_min_order_chk check (min_order_minor >= 0),
  constraint discount_codes_uses_chk check (
    used_count >= 0
    and (max_uses is null or max_uses > 0)
    and (per_customer_limit is null or per_customer_limit > 0)
  ),
  constraint discount_codes_window_chk check (
    starts_at is null or expires_at is null or expires_at > starts_at
  )
);

create unique index if not exists discount_codes_tenant_code_uidx
  on discount_codes (
    (coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    code
  );

create index if not exists discount_codes_active_idx
  on discount_codes (tenant_id, active);

create table if not exists discount_redemptions (
  id uuid primary key default gen_random_uuid(),
  code_id uuid not null references discount_codes(id) on delete cascade,
  customer_id uuid not null references customers(id) on delete cascade,
  order_id uuid not null references orders(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint discount_redemptions_code_order_uidx unique (code_id, order_id)
);

create index if not exists discount_redemptions_customer_idx
  on discount_redemptions (code_id, customer_id);

-- ---------------------------------------------------------------------------
-- warranty replacement requests
-- One open request per order. Open means pending or approved.
-- rejected and replaced leave the slot free for a later request.
-- ---------------------------------------------------------------------------

create table if not exists replacement_requests (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id) on delete cascade,
  customer_id uuid not null references customers(id) on delete cascade,
  tenant_id uuid references tenants(id) on delete cascade,
  reason text not null,
  status text not null default 'pending',
  owner_note text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  constraint replacement_requests_status_chk check (
    status in ('pending', 'approved', 'rejected', 'replaced')
  ),
  constraint replacement_requests_reason_len_chk check (
    char_length(reason) between 1 and 1000
  )
);

create unique index if not exists replacement_requests_one_open_uidx
  on replacement_requests (order_id)
  where status in ('pending', 'approved');

create index if not exists replacement_requests_status_idx
  on replacement_requests (tenant_id, status, created_at desc);

-- ---------------------------------------------------------------------------
-- rate limit hits
-- One row per bucket and window. bump_rate_limit increments under a row lock,
-- so two app instances cannot both pass the same count.
-- ---------------------------------------------------------------------------

create table if not exists rate_limit_hits (
  bucket text not null,
  window_start timestamptz not null,
  count integer not null default 0,
  primary key (bucket, window_start),
  constraint rate_limit_hits_count_chk check (count >= 0),
  constraint rate_limit_hits_bucket_chk check (char_length(bucket) between 1 and 200)
);

create index if not exists rate_limit_hits_window_idx
  on rate_limit_hits (window_start);

create or replace function bump_rate_limit(
  p_bucket text,
  p_window_start timestamptz
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  if p_bucket is null or char_length(p_bucket) < 1 or char_length(p_bucket) > 200 then
    raise exception 'invalid rate limit bucket';
  end if;
  if p_window_start is null then
    raise exception 'invalid rate limit window';
  end if;

  insert into rate_limit_hits (bucket, window_start, count)
  values (p_bucket, p_window_start, 1)
  on conflict (bucket, window_start)
  do update set count = rate_limit_hits.count + 1
  returning count into v_count;

  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- select-only RLS. No insert, update, or delete policy.
-- rate_limit_hits has RLS and no policy, so only the service role can see it.
-- ---------------------------------------------------------------------------

alter table support_threads enable row level security;
alter table support_messages enable row level security;
alter table discount_codes enable row level security;
alter table discount_redemptions enable row level security;
alter table replacement_requests enable row level security;
alter table rate_limit_hits enable row level security;

drop policy if exists "support_threads_owner_read" on support_threads;
create policy "support_threads_owner_read" on support_threads
  for select
  using (
    tenant_id is null
    and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
  );

drop policy if exists "support_threads_reseller_read" on support_threads;
create policy "support_threads_reseller_read" on support_threads
  for select
  using (
    tenant_id is not null
    and tenant_id in (select id from tenants where owner_user_id = auth.uid())
  );

drop policy if exists "support_messages_owner_read" on support_messages;
create policy "support_messages_owner_read" on support_messages
  for select
  using (
    exists (
      select 1 from support_threads
      where support_threads.id = support_messages.thread_id
        and support_threads.tenant_id is null
        and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
    )
  );

drop policy if exists "support_messages_reseller_read" on support_messages;
create policy "support_messages_reseller_read" on support_messages
  for select
  using (
    exists (
      select 1 from support_threads
      where support_threads.id = support_messages.thread_id
        and support_threads.tenant_id is not null
        and support_threads.tenant_id in (
          select id from tenants where owner_user_id = auth.uid()
        )
    )
  );

drop policy if exists "discount_codes_owner_read" on discount_codes;
create policy "discount_codes_owner_read" on discount_codes
  for select
  using (
    tenant_id is null
    and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
  );

drop policy if exists "discount_codes_reseller_read" on discount_codes;
create policy "discount_codes_reseller_read" on discount_codes
  for select
  using (
    tenant_id is not null
    and tenant_id in (select id from tenants where owner_user_id = auth.uid())
  );

drop policy if exists "discount_redemptions_owner_read" on discount_redemptions;
create policy "discount_redemptions_owner_read" on discount_redemptions
  for select
  using (
    exists (
      select 1 from discount_codes
      where discount_codes.id = discount_redemptions.code_id
        and discount_codes.tenant_id is null
        and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
    )
  );

drop policy if exists "discount_redemptions_reseller_read" on discount_redemptions;
create policy "discount_redemptions_reseller_read" on discount_redemptions
  for select
  using (
    exists (
      select 1 from discount_codes
      where discount_codes.id = discount_redemptions.code_id
        and discount_codes.tenant_id is not null
        and discount_codes.tenant_id in (
          select id from tenants where owner_user_id = auth.uid()
        )
    )
  );

drop policy if exists "replacement_requests_owner_read" on replacement_requests;
create policy "replacement_requests_owner_read" on replacement_requests
  for select
  using (
    tenant_id is null
    and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
  );

drop policy if exists "replacement_requests_reseller_read" on replacement_requests;
create policy "replacement_requests_reseller_read" on replacement_requests
  for select
  using (
    tenant_id is not null
    and tenant_id in (select id from tenants where owner_user_id = auth.uid())
  );

revoke all on table support_threads, support_messages, discount_codes, discount_redemptions, replacement_requests
  from public, anon, authenticated;
grant select on table support_threads, support_messages, discount_codes, discount_redemptions, replacement_requests
  to authenticated;
grant all on table support_threads, support_messages, discount_codes, discount_redemptions, replacement_requests
  to service_role;

revoke all on table rate_limit_hits from public, anon, authenticated;
grant all on table rate_limit_hits to service_role;

revoke all on function bump_rate_limit(text, timestamptz) from public, anon, authenticated;
grant execute on function bump_rate_limit(text, timestamptz) to service_role;
